L_IN_CG:
    setp.ge.u32 p_tmp, r_in_cg, r_cig;
    @p_tmp bra L_END_IN_CG;
        // ci = grp*cig + in_cg
        mul.lo.u32 r_tmp32, r_grp, r_cig;
        add.u32 r_ci, r_tmp32, r_in_cg;
        // kd loop with step=stride
        mov.u32 r_kd, r_kd_start;
        mov.u32 r_iterD, 0;
    L_KD2:
        setp.ge.u32 p_tmp, r_kd, rK;
        @p_tmp bra L_END_KD2;
            // di = t_d_base - iterD
            sub.s32 t_div, t_d_base, r_iterD;
