_ptx_module = None
def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module
def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_kernel")
class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        assert isinstance(kernel_size, int), "Only cubic kernels supported"
        assert isinstance(stride, int) and isinstance(padding, int) and isinstance(output_padding, int), "Only int stride/padding/output_padding supported"
        assert groups >= 1 and in_channels % groups == 0 and out_channels % groups == 0, "Invalid groups"
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        weight_shape = (in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size)
        self.weight = nn.Parameter(torch.empty(weight_shape))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.bias = None
        self.reset_parameters()
    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            init.uniform_(self.bias, -bound, bound)
    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 supported"
        assert x.dim() == 5, "Input must be NCDHW"
        N, Cin, Din, Hin, Win = x.shape
        assert Cin == self.in_channels, "Channel mismatch"
        K = self.kernel_size
        S = self.stride
        P = self.padding
        OP = self.output_padding
        G = self.groups
        Cout = self.out_channels
        # Output sizes according to ConvTranspose3d (dilation=1)
        Dout = (Din - 1) * S - 2 * P + (K - 1) + OP + 1
        Hout = (Hin - 1) * S - 2 * P + (K - 1) + OP + 1
        Wout = (Win - 1) * S - 2 * P + (K - 1) + OP + 1
        # Allocate output
        y = torch.empty((N, Cout, Dout, Hout, Wout), device=x.device, dtype=x.dtype)
        # Launch kernel
        module = _get_ptx_module()
        block_x = 128
        grid_x = (Wout + block_x - 1) // block_x
        grid_y = Hout
        grid_z = N * Cout * Dout
        has_bias = 1 if self.bias is not None else 0
        b_ptr_arg = self.bias if self.bias is not None else u64(0)
        # Dynamic shared memory for staged weights: (Cin/groups) * K^3 * sizeof(float)
        cig = Cin // G
        shared_memory = int(cig * (K * K * K) * 4)
        module.launch(
            "conv_transpose3d_kernel",
            grid=(int(grid_x), int(grid_y), int(grid_z)),
            block=(int(block_x), 1, 1),
            arguments=[
                x,                             # x_ptr
                self.weight,                   # w_ptr
                b_ptr_arg,                     # b_ptr or 0
                y,                             # y_ptr
                i32(N),
                i32(Cin),
                i32(Cout),
                i32(Din),
                i32(Hin),
                i32(Win),
                i32(Dout),
                i32(Hout),
                i32(Wout),
                i32(K),
                i32(S),
                i32(P),
                i32(G),
                u32(has_bias),
            ],
            shared_memory=int(shared_memory),
            stream=torch.cuda.current_stream(x.device),
        )
        return y
